import subprocess,re
files=subprocess.check_output(['git','diff','--name-only']).decode().split()
for f in files:
    if not f.endswith('.py'): continue
    head=subprocess.check_output(['git','show','HEAD:'+f]).decode().split('\n')
    cur=open(f).read().split('\n')
    for h in head:
        m=re.match(r'^(.*?)(\s+#\s*noqa.*)$',h)
        if m and h not in cur:
            for i,c in enumerate(cur):
                if c==m[1] or c==m[1].rstrip():
                    cur[i]=h;break
    open(f,'w').write('\n'.join(cur))
